import type { Shots, Transcript, TransitionKind } from "../kernel/project";
import { tr } from "../i18n/index.ts";

/**
 * The pure logic of see_frames media mode (source: "media"): turns the shot division into "which
 * shots to look at, how many pages, and which frames to sample for each montage".
 * It touches neither the network nor the store, and is unit-tested directly in node
 * (sequences.test.mjs). The montage itself is generated by ffmpeg on the server (/api/vision/sheet
 * in server/vite-plugin-vision.ts); only the planning is computed here.
 */

export interface SceneSpec {
  /** Shot number starting from 1, consistent with the order of list_shots */
  index: number;
  start: number;
  end: number;
  inTransition: TransitionKind | null;
  outTransition: TransitionKind | null;
}

export interface SequencesPlan {
  scenes: SceneSpec[];
  page: number;
  pages: number;
  perPage: number;
  grid: 4 | 9;
  /** How many shots there are after filtering (from / to / scene) */
  matched: number;
  totalScenes: number;
  nextPage: number | null;
  prevPage: number | null;
}

export const DEFAULT_PER_PAGE = 6;
export const MAX_PER_PAGE = 12;
/** When shot detection has not been run (or failed), cut into segments at a fixed interval */
export const FALLBACK_STEP_SEC = 10;
/**
 * Frame sampling is shifted slightly past the shot start, to avoid the frame that sits exactly on a
 * transition
 */
export const FRAME_EPS = 0.05;

/** Shot detection result → shot list; with no result, cut at a fixed interval and mark fallback */
export function scenesOf(shots: Shots | null | undefined, durationSec: number, step = FALLBACK_STEP_SEC): { scenes: SceneSpec[]; fallback?: "fixed-interval" } {
  if (shots?.shots?.length) {
    return {
      scenes: shots.shots.map((s, i) => ({ index: i + 1, start: s.start, end: s.end, inTransition: s.inTransition ?? null, outTransition: s.outTransition ?? null })),
    };
  }
  const total = Math.max(0, Number(durationSec) || 0);
  const scenes: SceneSpec[] = [];
  if (total <= 0) return { scenes, fallback: "fixed-interval" };
  const n = Math.max(1, Math.ceil(total / step));
  for (let i = 0; i < n; i++) {
    const start = i * step;
    scenes.push({ index: i + 1, start, end: Math.min(total, start + step), inTransition: null, outTransition: null });
  }
  return { scenes, fallback: "fixed-interval" };
}

export interface PlanOptions {
  page?: number;
  perPage?: number;
  grid?: number;
  scene?: number;
  from?: number;
  to?: number;
}

/**
 * Filtering + paging. If scene is specified, only that one is viewed (9 cells by default), and
 * paging is ignored
 */
export function planSequences(all: SceneSpec[], opts: PlanOptions = {}): SequencesPlan {
  const totalScenes = all.length;
  if (opts.scene !== undefined) {
    const n = Number(opts.scene);
    if (!Number.isInteger(n) || n < 1 || n > totalScenes) throw new Error(tr("scene must be between 1 and {0}, got {1}", totalScenes, JSON.stringify(opts.scene)));
    const grid = opts.grid === 4 ? 4 : 9;
    return { scenes: [all[n - 1]], page: 1, pages: 1, perPage: 1, grid, matched: 1, totalScenes, nextPage: null, prevPage: null };
  }
  const from = opts.from !== undefined ? Number(opts.from) : -Infinity;
  const to = opts.to !== undefined ? Number(opts.to) : Infinity;
  if (opts.from !== undefined && !Number.isFinite(from)) throw new Error(tr("from must be a number of seconds"));
  if (opts.to !== undefined && !Number.isFinite(to)) throw new Error(tr("to must be a number of seconds"));
  if (from > to) throw new Error(tr("from must not be greater than to"));
  // Every shot that overlaps the range counts (when the user says "look at 30 to 60 seconds", the
  // shot straddling the 30-second mark should be viewed too)
  const matched = all.filter((s) => s.end > from && s.start < to);
  const perPage = Math.max(1, Math.min(MAX_PER_PAGE, Math.round(Number(opts.perPage) || DEFAULT_PER_PAGE)));
  const grid: 4 | 9 = opts.grid === 9 ? 9 : 4;
  const pages = Math.max(1, Math.ceil(matched.length / perPage));
  const page = Math.max(1, Math.min(pages, Math.round(Number(opts.page) || 1)));
  const scenes = matched.slice((page - 1) * perPage, page * perPage);
  return {
    scenes, page, pages, perPage, grid, matched: matched.length, totalScenes,
    nextPage: page < pages ? page + 1 : null,
    prevPage: page > 1 ? page - 1 : null,
  };
}

/**
 * Which frames (in seconds) are sampled from a shot: evenly spaced, with the start nudged slightly
 * later; same sampling as the fps filter of ffmpeg on the server
 */
export function frameTimes(start: number, end: number, grid: number): number[] {
  const dur = Math.max(0, end - start - FRAME_EPS);
  const n = Math.max(1, grid | 0);
  const out: number[] = [];
  for (let k = 0; k < n; k++) out.push(Math.round((start + FRAME_EPS + (dur * k) / n) * 100) / 100);
  return out;
}

/**
 * The caption text within this time span (only exists if there is a transcription); every segment
 * that overlaps the range counts
 */
export function transcriptFor(transcript: Transcript | null | undefined, start: number, end: number): string {
  if (!transcript?.segments?.length) return "";
  return transcript.segments
    .filter((s) => s.end > start && s.start < end)
    .map((s) => s.text.trim())
    .filter(Boolean)
    .join(" ");
}
